findings.reproduction:
from tqdm.contrib import tenumerate

seen = []

class Recorder:
    def __init__(self, iterable, total=None, **kwargs):
        seen.append(total)
        self.iterable = iterable

    def __iter__(self):
        return iter(self.iterable)

assert list(tenumerate(['a', 'b'], start=3, total=9, tqdm_class=Recorder)) == [(3, 'a'), (4, 'b')]
assert seen == [9]
